    private val maps = mapOf("ru" to ru, "kk" to kk, "en" to en, "zh" to zh, "de" to de, "es" to es, "fr" to fr, "tr" to tr)

    fun normalizeLanguage(code:String?):String {
        val raw=code.orEmpty().lowercase(Locale.ROOT)
        return when {
            raw.startsWith("zh") -> "zh"
            raw.startsWith("kk") -> "kk"
            raw.startsWith("ru") -> "ru"
            raw.startsWith("de") -> "de"
            raw.startsWith("es") -> "es"
            raw.startsWith("fr") -> "fr"
            raw.startsWith("tr") -> "tr"
            raw.startsWith("en") -> "en"
            else -> "en"
        }
    }

    fun t(lang:String,key:String):String { val code=normalizeLanguage(lang); return calendarExtras[code]?.get(key) ?: v093Extras[code]?.get(key) ?: maps[code]?.get(key) ?: en[key] ?: ru[key] ?: key }

    fun languageName(code:String):String = when(normalizeLanguage(code)){
        "ru"->"Русский"; "kk"->"Қазақша"; "en"->"English"; "zh"->"中文"; "de"->"Deutsch"; "es"->"Español"; "fr"->"Français"; "tr"->"Türkçe"; else->"English"
    }


    fun languageFlag(code:String):String = when(normalizeLanguage(code)){
        "kk"->"🇰🇿"; "ru"->"🇷🇺"; "en"->"🇬🇧"; "zh"->"🇨🇳"; "de"->"🇩🇪"; "es"->"🇪🇸"; "fr"->"🇫🇷"; "tr"->"🇹🇷"; else->"🌐"
    }

    fun localeTag(lang:String):String = when(normalizeLanguage(lang)){
        "ru"->"ru-RU"; "kk"->"kk-KZ"; "en"->"en-US"; "zh"->"zh-CN"; "de"->"de-DE"; "es"->"es-ES"; "fr"->"fr-FR"; "tr"->"tr-TR"; else->"en-US"
    }

    fun locale(lang:String):Locale = Locale.forLanguageTag(localeTag(lang))

    fun weekdayLabels(lang:String):List<String> = when(normalizeLanguage(lang)){
        "ru"->listOf("Пн","Вт","Ср","Чт","Пт","Сб","Вс")
        "kk"->listOf("Дс","Сс","Ср","Бс","Жм","Сб","Жс")
        "zh"->listOf("一","二","三","四","五","六","日")
        "de"->listOf("Mo","Di","Mi","Do","Fr","Sa","So")
        "es"->listOf("Lu","Ma","Mi","Ju","Vi","Sá","Do")
        "fr"->listOf("Lu","Ma","Me","Je","Ve","Sa","Di")
        "tr"->listOf("Pt","Sa","Ça","Pe","Cu","Ct","Pa")
        else->listOf("Mon","Tue","Wed","Thu","Fri","Sat","Sun")
    }
}
